-- ── story 2-4a: damaged and short receipt quantities ─────────────────────
-- Generated by drizzle-kit (the four columns on `goods_receipt_lines`) and
-- hand-amended below the generated part: the fail-fast guard, the CHECK swap
-- on `qty`, the two pairing CHECKs, the re-code of pre-rule `DAMAGED`
-- locations and the post-migration probe (drizzle-kit is blind to all of
-- it; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: four columns with constant defaults (`damaged_qty` / `short_qty`
-- 0, the reasons null) — no rewrite, and every existing line already
-- satisfies every new CHECK (its `qty > 0` held under 0013/0026, its new
-- columns are 0 / null). The only data rewritten is the code of any user
-- zone or bin coded `DAMAGED` (re-coded, each named in a NOTICE — see the
-- block below). No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- The CHECK swap: `qty` now means the GOOD units only and may be 0 (an
-- all-damaged line), so `goods_receipt_lines_qty_positive` (`qty > 0`) is
-- dropped and replaced by `_qty_nonnegative` (`qty >= 0`) plus
-- `_received_positive` (`qty + damaged_qty > 0` — a line always carries
-- arrivals; a short with nothing received is not recordable). The existing
-- `goods_receipt_lines_applied_le_physical` (`applied_qty <= qty`) stays: a
-- damaged unit never applies.
--
-- Lock cost: the ADD COLUMNs take a brief ACCESS EXCLUSIVE lock on
-- `goods_receipt_lines` (constant defaults — no rewrite); the ADD CONSTRAINT
-- CHECKs scan the table once each under that lock.

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'goods_receipt_lines' AND column_name = 'damaged_qty'
	) THEN
		RAISE EXCEPTION 'migration 0087: goods_receipt_lines.damaged_qty already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD COLUMN "damaged_qty" bigint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD COLUMN "damage_reason_code" text;--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD COLUMN "short_qty" bigint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD COLUMN "short_reason_code" text;--> statement-breakpoint
-- ── hand-amended: the CHECK swap on qty (migration SQL only) ─────────────
ALTER TABLE "goods_receipt_lines" DROP CONSTRAINT "goods_receipt_lines_qty_positive";--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD CONSTRAINT "goods_receipt_lines_qty_nonnegative" CHECK ("qty" >= 0);--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD CONSTRAINT "goods_receipt_lines_received_positive" CHECK ("qty" + "damaged_qty" > 0);--> statement-breakpoint
-- ── hand-amended: the pairing CHECKs — `IS NOT NULL` before `IN` (guide §3:
-- `NULL IN (…)` is NULL, which a CHECK admits). The vocabularies are
-- `DAMAGE_REASON_CODES` / `SHORT_REASON_CODES` (src/modules/inbound/
-- receipt-condition.ts), pinned against these CHECKs by
-- test/receipt-condition.spec.ts.
ALTER TABLE "goods_receipt_lines" ADD CONSTRAINT "goods_receipt_lines_damage_pairing" CHECK (
	("damaged_qty" = 0 AND "damage_reason_code" IS NULL)
	OR ("damaged_qty" > 0 AND "damage_reason_code" IS NOT NULL
		AND "damage_reason_code" IN ('crushed','wet','torn-packaging','broken','leaking','pest','other'))
);--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD CONSTRAINT "goods_receipt_lines_short_pairing" CHECK (
	("short_qty" = 0 AND "short_reason_code" IS NULL)
	OR ("short_qty" > 0 AND "short_reason_code" IS NOT NULL
		AND "short_reason_code" IN ('not-shipped','short-packed','lost-in-transit','other'))
);--> statement-breakpoint
-- ── re-code the collisions: user zones and bins already coded DAMAGED ─────
-- From this story on the code `DAMAGED` is reserved for the system damaged
-- zone and bin (zone and bin create refuse it, 409 `reserved-location-code`).
-- A user location coded DAMAGED that predates the rule could never be
-- cleared otherwise: codes cannot be renamed, a retired bin keeps
-- `bins_warehouse_id_code_unique`, and zones cannot be retired — so it would
-- block every damaged receipt in its warehouse forever (code review CR1).
-- Every such user zone and bin (`system_owned = false`, retired or not —
-- zones carry no system flag and no system DAMAGED zone exists before this
-- story, so every zone coded DAMAGED is a user's) is re-coded to
-- `DAMAGED-` + the first 8 characters of its id, each named in a NOTICE.
-- After this, `damaged-bin-conflict` is a defensive arm only.
DO $$
DECLARE
	r record;
	new_code text;
BEGIN
	FOR r IN SELECT "id", "warehouse_id" FROM "zones" WHERE "code" = 'DAMAGED' ORDER BY "id" LOOP
		new_code := 'DAMAGED-' || left(r."id"::text, 8);
		UPDATE "zones" SET "code" = new_code, "updated_at" = now() WHERE "id" = r."id";
		RAISE NOTICE 'migration 0087: warehouse % — zone % re-coded DAMAGED → %.', r."warehouse_id", r."id", new_code;
	END LOOP;
	FOR r IN SELECT "id", "warehouse_id" FROM "bins" WHERE "code" = 'DAMAGED' AND "system_owned" = false ORDER BY "id" LOOP
		new_code := 'DAMAGED-' || left(r."id"::text, 8);
		UPDATE "bins" SET "code" = new_code, "updated_at" = now() WHERE "id" = r."id";
		RAISE NOTICE 'migration 0087: warehouse % — bin % re-coded DAMAGED → %.', r."warehouse_id", r."id", new_code;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "zones" WHERE "code" = 'DAMAGED')
	   OR EXISTS (SELECT 1 FROM "bins" WHERE "code" = 'DAMAGED' AND "system_owned" = false) THEN
		RAISE EXCEPTION 'migration 0087: a user location coded DAMAGED survived the re-code.';
	END IF;
END $$;
--> statement-breakpoint
-- ── the post-migration assertion (the 0086 model) ─────────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (guide §3).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	g uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: a good-only line (the pre-2-4a shape), an
	-- all-damaged line (qty 0, applied 0, damaged > 0), a split line with a
	-- short, every damage and short code.
	BEGIN
		INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty","damage_reason_code","short_qty","short_reason_code")
		VALUES
			(gen_random_uuid(), t, g, s, 1000, 1000, 0, NULL, 0, NULL),
			(gen_random_uuid(), t, g, s, 0, 0, 5000, 'wet', 0, NULL),
			(gen_random_uuid(), t, g, s, 90000, 90000, 10000, 'crushed', 5000, 'not-shipped'),
			(gen_random_uuid(), t, g, s, 1, 0, 1, 'torn-packaging', 1, 'short-packed'),
			(gen_random_uuid(), t, g, s, 1, 0, 1, 'broken', 1, 'lost-in-transit'),
			(gen_random_uuid(), t, g, s, 1, 0, 1, 'leaking', 1, 'other'),
			(gen_random_uuid(), t, g, s, 1, 0, 1, 'pest', 0, NULL),
			(gen_random_uuid(), t, g, s, 1, 0, 1, 'other', 0, NULL),
			-- a short-only good line (qty > 0, nothing damaged, short > 0)
			(gen_random_uuid(), t, g, s, 95000, 95000, 0, NULL, 5000, 'not-shipped');
		RAISE EXCEPTION USING ERRCODE = 'P0087', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0087: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0087' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint. (A negative `qty` is
	-- not probed on its own: `applied_qty >= 0` and `applied_qty <= qty`
	-- already refuse it, and Postgres tests CHECKs in name order, so the
	-- `applied_*` pair always fires before `_qty_nonnegative` — which is kept
	-- as the column's own statement of the rule.)
	FOREACH probe IN ARRAY ARRAY[
		'nothing received', 'damaged without reason', 'damage reason with 0', 'damage code unknown',
		'damaged negative', 'short without reason', 'short reason with 0', 'short code unknown', 'short negative', 'damaged applied'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'nothing received' THEN 'goods_receipt_lines_received_positive'
			WHEN 'damaged without reason' THEN 'goods_receipt_lines_damage_pairing'
			WHEN 'damage reason with 0' THEN 'goods_receipt_lines_damage_pairing'
			WHEN 'damage code unknown' THEN 'goods_receipt_lines_damage_pairing'
			WHEN 'damaged negative' THEN 'goods_receipt_lines_damage_pairing'
			WHEN 'short without reason' THEN 'goods_receipt_lines_short_pairing'
			WHEN 'short reason with 0' THEN 'goods_receipt_lines_short_pairing'
			WHEN 'short code unknown' THEN 'goods_receipt_lines_short_pairing'
			WHEN 'short negative' THEN 'goods_receipt_lines_short_pairing'
			ELSE 'goods_receipt_lines_applied_le_physical'
		END;
		BEGIN
			CASE probe
				WHEN 'nothing received' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty")
					VALUES (gen_random_uuid(), t, g, s, 0, 0, 0);
				WHEN 'damaged without reason' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, 1000);
				WHEN 'damage reason with 0' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty","damage_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, 0, 'wet');
				WHEN 'damage code unknown' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty","damage_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, 1000, 'dented');
				WHEN 'damaged negative' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty","damage_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 5000, 5000, -1000, 'wet');
				WHEN 'short without reason' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","short_qty")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, 1000);
				WHEN 'short reason with 0' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","short_qty","short_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, 0, 'not-shipped');
				WHEN 'short code unknown' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","short_qty","short_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, 1000, 'stolen');
				WHEN 'short negative' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","short_qty","short_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 1000, 1000, -1000, 'other');
				WHEN 'damaged applied' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","damaged_qty","damage_reason_code")
					VALUES (gen_random_uuid(), t, g, s, 0, 1000, 1000, 'wet');
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0087: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "goods_receipt_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0087: a probe row survived.';
	END IF;
END $$;
